def solve(n, m, s, t, edges):
    """
    edges is list of (u, v, w, original_index) tuples
    Returns (min_cost, num_edges_closed, edge_indices) or None
    """
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v, w, idx = edges[i][0], edges[i][1], edges[i][2], edges[i][3]
        adj[u].append([v, i, w])
        adj[v].append([u, i, w])

    # BFS to check connectivity with blocked edges
    def can_reach(blocked_edges):
        if s == t:
            return True
        visited = [False] * (n + 1)
        visited[s] = True
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, idx, w in adj[u]:
                if idx in blocked_edges:
                    continue
                if not visited[v]:
                    visited[v] = True
                    if v == t:
                        return True
                    queue.append(v)
        return visited[t]

    # Check if already disconnected
    if not can_reach(set()):
        return (0, 0, [])

    # Try removing 1 edge
    for i in range(m):
        idx = i
        if not can_reach({idx}):
            return (edges[i][2], 1, [edges[i][3]])

    # Try removing 2 edges
    min_cost = float('inf')
    best_pair = None

    for i in range(m):
        blocked = {i}
        if not can_reach(blocked):
            continue

        for j in range(i + 1, m):
            blocked2 = blocked | {j}
            if not can_reach(blocked2):
                cost = edges[i][2] + edges[j][2]
                if cost < min_cost:
                    min_cost = cost
                    best_pair = (i, j)

    if best_pair is not None:
        i, j = best_pair
        return (min_cost, 2, [edges[i][3], edges[j][3]])

    return None

