    """
    Problem appears to be counting the number of trailing zeros in binary representation,
    or equivalently, find the exponent of 2 in the prime factorization of n.
    """
    n = int(s.strip())
    if n == 0:
        return '0'

    count = 0
    while n > 0:
        if n % 2 == 0:
            count += 1
            n //= 2
        else:
            break

    return str(count)

