def is_gp(seq):
    """
    Check if a sequence is a geometric progression.
    Returns True if it's a valid GP, False otherwise.
    """
    n = len(seq)
    if n <= 1:
        return True

    all_zeros = all(x == 0 for x in seq)
    if all_zeros:
        return True

    # Find first non-zero element
    first_nonzero = -1
    for i in range(n):
        if seq[i] != 0:
            first_nonzero = i
            break

    if first_nonzero == -1:
        return True  # All zeros case handled above

    # Determine common ratio and base
    # The sequence from first_nonzero onwards must follow GP pattern
    expected_ratio = None

    for i in range(first_nonzero + 1, n):
        if seq[i] == 0 and seq[i-1] != 0:
            return False  # Non-zero followed by zero

        if seq[i-1] != 0 and seq[i] != 0:
            # Skip if this is the first ratio calculation
            if expected_ratio is None:
                expected_ratio = seq[i] / seq[i-1]
            else:
                if abs(seq[i] * 1.0 - expected_ratio * seq[i-1]) > 1e-9:
                    # Check consistency before deciding it's not GP
                    # Be careful about floating point issues
                    pass

    # Re-verify with the calculated ratio
    expected_ratio = None
    for i in range(1, n):
        if seq[i-1] == 0 and seq[i] == 0:
            continue  # consecutive zeros are fine
        if seq[i-1] == 0:
            if seq[i] != 0:
                return False  # non-zero after zero with ratio undefined
            continue  # need to check if all zeros from here
        if seq[i] == 0 and seq[i-1] != 0:
            return False  # zero after non-zero
        if expected_ratio is None:
            expected_ratio = seq[i] / seq[i-1]
        else:
            if abs(seq[i] - expected_ratio * seq[i-1]) > 1e-9:
                return False

    return True


