def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return '0'

    n, k = map(int, lines[0].split())

    if n == 1:
        return '0'

    adj = [[] for _ in range(n + 1)]
    for i in range(len(lines) - 1):
        u, v = map(int, lines[1 + i].split())
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    order = []

    def dfs_order(u, p):
        parent[u] = p
        order.append(u)
        for v in adj[u]:
            if v != p:
                dfs_order(v, u)

    dfs_order(1, 0)
    order.reverse()

    INF = float('inf')

    # dp[u][sz] = min_cuts (component u has size sz, 1 <= sz <= k)
    from collections import defaultdict

    dp = [defaultdict(lambda: INF) for _ in range(n + 1)]

    for u in order:
        dp[u][1] = 0

        children = [v for v in adj[u] if v != parent[u]]
        if not children:
            continue

        for v in children:
            new_dp = defaultdict(lambda: INF)

            for sz1, c1 in dp[u].items():
                for sz2, c2 in dp[v].items():
                    if sz1 + sz2 <= k:
                        new_dp[sz1 + sz2] = min(new_dp[sz1 + sz2], c2)
                    if sz1 + 1 <= k:
                        new_dp[sz1 + 1] = min(new_dp[sz1 + 1], c1 + 1)

            dp[u] = new_dp

    ans = min(dp[u][k] for u in range(1, n + 1) if dp[u][k] < INF)

    return (str(ans) + '\n' + '\n'.join(map(str, range(1, ans + 1))) if ans > 0 else '0')

import random

def orientation(p, q, r):
    """Returns orientation of ordered triplet (p, q, r)"""
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if abs(val) < 1e-9: return 0  # Collinear (shouldn't happen per problem guarantee)
    return 1 if val > 0 else 2

def on_segment(p, q, r):
    """Check if point p lies on segment qr"""
    return min(q[0], r[0]) <= p[0] <= max(q[0], r[0]) and min(q[1], r[1]) <= p[1] <= max(q[1], r[1])

def segments_intersect(p1, q1, p2, q2):
    """Check if segments p1-q1 and p2-q2 intersect"""
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)
    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)

    if o1 != o2 and o3 != o4:
        return True

    if o1 == 0 and on_segment(p1, p2, q2): return True
    if o2 == 0 and on_segment(q1, p2, q2): return True
    if o3 == 0 and on_segment(p2, q1, q1): return True
    if o4 == 0 and on_segment(q2, q1, p1): return True

    return False

def check_matching(matching, n, spaceships, bases):
    """Check if the matching is valid (no intersecting segments)"""
    for i in range(n):
        for j in range(i + 1, n):
            s1 = spaceships[i]
            b1 = bases[matching[i] - 1]
            s2 = spaceships[j]
            b2 = bases[matching[j] - 1]
            if segments_intersect(s1, b1, s2, b2):
                return False
    return True

