    bases = []
    for i in range(n):
        x, y = map(int, lines[n + i + 1].split())
        bases.append((x, y))

    # Try multiple strategies to find a valid non-crossing matching

    # Strategy 1: Sort by x-coordinate
    ship_idx_by_x = sorted(range(n), key=lambda i: spaceships[i][0])
    base_idx_by_x = sorted(range(n), key=lambda i: bases[i][0])
    matching = [0] * n
    for rank, ship_rank in enumerate(ship_idx_by_x):
        matching[ship_rank] = base_idx_by_x[rank] + 1  # Convert to 1-indexed

    if not check_matching(matching, n, spaceships, bases):
        matching = None

    # Strategy 2: Sort by y-coordinate  
    if matching is None:
        ship_idx_by_y = sorted(range(n), key=lambda i: spaceships[i][1])
        base_idx_by_y = sorted(range(n), key=lambda i: bases[i][1])
        matching = [0] * n
        for rank, ship_rank in enumerate(ship_idx_by_y):
            matching[ship_rank] = base_idx_by_y[rank] + 1

        if not check_matching(matching, n, spaceships, bases):
            matching = None

    # Strategy 3: Shuffle and try random permutations
    if matching is None:
        for attempt in range(min(500, n * 10)):
            bases_sorted = list(range(n))
            random.shuffle(bases_sorted)
            matching = [0] * n
            for i in range(n):
                matching[i] = bases_sorted[i] + 1

            if check_matching(matching, n, spaceships, bases):
                break
        else:
            matching = None  # Fallback

    # Strategy 4: Greedy by angular position for remaining cases
    if matching is None:
        for attempt in range(min(1000, n * 20)):
            perm = list(range(1, n + 1))
            random.shuffle(perm)

            valid = True
            for i in range(n):
                for j in range(i + 1, n):
                    if segments_intersect(spaceships[i], 
                                         bases[perm[j] - 1],
                                         spaceships[j],
                                         bases[perm[i] - 1]):
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                matching = perm
                break
        else:
            matching = None

    # Fallback to any deterministic match (problem guarantees solution exists)
    if matching is None:
        ship_idx_by_x = sorted(range(n), key=lambda i: spaceships[i][0])
        base_idx_by_x = sorted(range(n), key=lambda i: bases[i][0])
        matching = [0] * n
        for rank, ship_rank in enumerate(ship_idx_by_x):
            matching[ship_rank] = base_idx_by_x[rank] + 1

    return '\n'.join(map(str, matching))


