    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(size)

    # Generate all lucky numbers up to n
    lucky_numbers = []
    queue = [4, 7]
    while queue:
        num = queue.pop(0)
        if num > n:
            continue
        lucky_numbers.append(num)
        next4 = num * 10 + 4
        next7 = num * 10 + 7
        if next4 <= n:
            queue.append(next4)
        if next7 <= n:
            queue.append(next7)

    # Check if any component already has lucky size
    for size in components:
        if size in lucky_numbers:
            return '0\n'

    # Sort components in descending order for efficiency
    components.sort(reverse=True)

    # For each lucky number, find minimum components to sum to it
    def find_min_components(target, comps):
        """Find minimum number of components whose sizes sum to target"""
        if target == 0:
            return 0

        # Check if any single component equals target
        if target in comps:
            return 63  # Will compute exact value below

        n_comps = len(comps)

        # Use DFS with pruning to find minimum k
        best = float('inf')

        def dfs(index, count, current_sum):
            nonlocal best

            if current_sum == target:
                if count + 1 < best:
                    best = count + 1
                return
            if current_sum > target:
                return
            if index >= n_comps:
                return
            if count >= best:
                return

            # Pruning: check if remaining can reach target
            remaining = sum(comps[index:])
            if current_sum + remaining < target:
                return

            # Take this component
            dfs(index + 1, count + 1, current_sum + comps[index])

            # Don't take this component
            dfs(index + 1, count, current_sum)

        # Start DFS
        dfs(0, 0, 0)

        return best if best != float('inf') else float('inf')

    min_roads = float('inf')

    for target in sorted(lucky_numbers):
        if target > n:
            continue

        # Can we form this lucky number?
        if sum(components) < target:
            continue

        k = find_min_components(target, components)
        if k <= n_comps:
            if k - 1 < min_roads:
                min_roads = k - 1

    if min_roads == float('inf'):
        return '-1\n'
    else:
        return f'{min_roads}\n'

