    v2 = [p3[0]-p2[0], p3[1]-p2[1], p3[2]-p2[2]]
    v3 = [p1[0]-p3[0], p1[1]-p3[1], p1[2]-p3[2]]

    # Set up the system M*c = d where c is the center
    def dot(v1, v2):
        return v1[0]*v2[0] + v1[1]*v2[1] + v1[2]*v2[2]

    mx = (p2[0]+p1[0])/2, my = (p2[1]+p1[1])/2, mz = (p2[2]+p1[2])/2
    d1 = dot(v1, (mx, my, mz))

    xx = (p3[0]+p2[0])/2, yy = (p3[1]+p2[1])/2, zz = (p3[2]+p2[2])/2
    d2 = dot(v2, (xx, yy, zz))

    aa = (p1[0]+p3[0])/2, ab = (p1[1]+p3[1])/2, ac = (p1[2]+p3[2])/2
    d3 = dot(v3, (aa, ab, ac))

    M = [v1, v2, v3]
    d = [d1, d2, d3]

    # Gauss elimination
    A = [[M[i][j] for j in range(3)] for i in range(3)]
    for i in range(3):
        for j in range(i+1, 3):
            if abs(A[i][i]) < 1e-12:
                continue

            t = A[j][i] / A[i][i]
            for k in range(i, 4):
                A[j][k] -= t * A[i][k]
            if abs(A[i][i]) < 1e-12:
                continue
            else:
                d[j] -= t * d[i]

    result = [d[i] / A[i][i] if abs(A[i][i]) > 1e-12 else 0.0 for i in range(2, -1, -1)]

    return result

