def solution(input_str):
    """
    Find the k-th lexicographically smallest canonical string of length n.

    Equivalence: s ~ s_reverse, s_complement, s_reverse_complement.
    Canonical = lexicographically smallest in the equivalence class.

    Approach: Build string position by position, determining each bit.
    """

    n, k = map(int, input_str.strip().split())

    def complement(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    def reverse(s):
        return s[::-1]

    def min_transform(s):
        """Get canonical form of string s"""
        t1, t2, t3, t4 = s, complement(s), reverse(s), reverse(complement(s))
        return min(t1, t2, t3, t4)

    def is_canonical(s):
        """Check if s is canonical among its transforms"""
        t1, t2, t3, t4 = s, complement(s), reverse(s), reverse(complement(s))
        return s == min(t1, t2, t3, t4)

    # Build k-th canonical string
    result = []

    # Iteratively determine each position
    for pos in range(n):
        prefix = ''.join(result)

        for try_bit in ['0', '1']:
            candidate = prefix + try_bit

            # Check if candidate is lexicographically smallest in its class
            c0 = complement(candidate)
            c1 = reverse(candidate)
            c2 = reverse(complement(candidate))

            # Compare candidate with all transforms
            is_best = True
            for t in [c0, c1, c2]:
                if t < candidate:
                    is_best = False
                    break

            if is_best:
                result.append(try_bit)

    return ''.join(result)

