        if num < 2:
            return False
        if num == 2 or num == 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        for i in range(5, int(num**0.5) + 1, 6):
            if num % i == 0 or num % (i + 2) == 0:
                return False
        return True

    def find_multiplicative_order(a, m):
        """Find the multiplicative order of a modulo m"""
        a = a % m
        if a == 0:
            return -1
        if a == 1:
            return 1
        phi = m - 1  # For prime m
        divisors = []
        d = 1
        while d * d <= phi:
            if phi % d == 0:
                divisors.append(d)
                if d * d != phi:
                    divisors.append(phi // d)
            d += 1
        for d in divisors:
            if pow(a, d, m) == 1:
                return d
        return phi

