        for b in range(n + 1):
            if dp[b] == 0:
                continue

            # Customer A: gives us 50-yuan, balance increases
            if b + 1 <= n:
                new_dp[b + 1] = (new_dp[b + 1] + dp[b]) % p

            # Customer B: we give 50-yuan change, balance decreases (only if b > 0)
            if b > 0:
                new_dp[b - 1] = (new_dp[b - 1] + dp[b]) % p

            # Customer C (VIP): no payment, no change to balance
            new_dp[b] = (new_dp[b] + dp[b]) % p

        dp = new_dp

    # Sum up all valid final balances in range [l, r]
    result = sum(dp[b] for b in range(l, r + 1)) % p
    return str(result)

