    overlap = {}

    for i in range(len(strings)):
        for j in range(i + 1, len(strings)):
            s_i = strings[i]
            s_j = strings[j]

            # Find maximum overlap between end of s_i and start of s_j
            max_overlap = 0
            for length in range(1, min(len(s_i), len(s_j)) + 1):
                if s_i.endswith(s_j[:length]) and s_j.startswith(s_i[-length:]):
                    max_overlap = max(max_overlap, length)
                    break

            overlap[(i, j)] = max_overlap

    # Greedy construction
    result = strings[0]

    for i in range(1, len(strings)):
        s = strings[i]
        # Try to overlap s with last string in result
        best_end_overlap = -1
        for end_idx in range(len(result) - 1, -1, -1):
            overlap_len = 0
            match = False

            for length in range(1, min(len(result) - end_idx, len(s)) + 1):
                if result[end_idx:end_idx + length] == s[:length]:
                    if length > overlap_len:
                        overlap_len = length
                        match = True
                        break

            if match:
