def solution(input_str: str) -> str:
    """
    Solves the interactive grid navigation problem.

    Args:
        input_str: The test input string containing n, m, grid, and interaction data

    Returns:
        A string of moves (U/D/L/R separated by newlines) to navigate from (1,1) to 'F'
    """
    from collections import deque

    lines = input_str.strip().split('\n')
    idx = 0

    def parse_int_pair():
        nonlocal idx
        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        parts = lines[idx].strip().split()
        idx += 1
        return (int(parts[0]), int(parts[1]))

    def parse_grid_line():
        nonlocal idx
        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        return lines[idx].strip()

    # Read n, m
    n, m = parse_int_pair()

    # Read grid
    grid = []
    for i in range(n):
        grid.append(parse_grid_line())

    # Find target position (0-indexed)
    target = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                target = (i, j)
                break
        if target:
            break

    if target is None:
        return ""

    # Direction mappings
    DIR_DELTA = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    def get_actual_delta(btn, swap_lr, swap_ud):
        dr, dc = DIR_DELTA[btn]
        if swap_ud and btn in ('U', 'D'):
            dr = -dr
        if swap_lr and btn in ('L', 'R'):
            dc = -dc
        return dr, dc

    def find_path(swap_lr, swap_ud):
        queue = deque([(0, 0, [])])
        visited = {(0, 0)}

        while queue:
            r, c, path = queue.popleft()
            if (r, c) == target:
                return path

            for btn in ['U', 'D', 'L', 'R']:
                dr, dc = get_actual_delta(btn, swap_lr, swap_ud)
                nr, nc = r + dr, c + dc

                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] != '*' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc, path + [btn]))

        return None

    # Try different swap configurations
    possible = [
        (0, 0), (0, 1), (1, 0), (1, 1)
    ]

    for lr, ud in possible:
        path = find_path(lr, ud)
        if path is not None:
            return '\n'.join(path) + '\n'

    return ""

