        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = map(int, parts)
            u, v = u - 1, v - 1
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components
    visited = [False] * n
    components = []
    for i in range(n):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                comp.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(comp)

    def count_independent_sets_local(comp_nodes, component_adj):
        """Count number of independent set assignments for the component."""
        size = len(comp_nodes)
        if size == 0:
            return 1

        # Build local adjacency matrix
        node_idx = {comp_nodes[i]: i for i in range(size)}
        adj_mat = [[False] * size for _ in range(size)]
        for i in range(size):
            for neighbor in component_adj[i]:
                if neighbor in node_idx:
                    adj_mat[i][node_idx[neighbor]] = True
                    adj_mat[node_idx[neighbor]][i] = True

        # Use BFS/DFS approach for counting
        # Since we need assignments where no two adjacent vertices both have same label
        # This is equivalent to independent set counting

        # For small components, use direct enumeration
        max_sets = 1 << size

        # We need to count properly - intersection of independent set conditions
        # For simplicity, use meet-in-the-middle or DP

        # For bipartite check (needed for sum-1)
