                stack = [start]
                color[start] = 0
                while stack:
                    u = stack.pop()
                    for v in adj_list[u]:
                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            stack.append(v)
                        elif color[v] == color[u]:
                            return False
            return True

        # For counting independent sets using branch and bound
        from functools import lru_cache

        def count_independent_sets_recursive(idx, current_set):
            # Check if we can add remaining nodes
            for node in range(idx, size):
                if node in current_set:
                    continue
                # Check if node conflicts with current set
                conflicts = False
                for member in current_set:
                    if adj_mat[member][node]:
                        conflicts = True
                        break
                if conflicts:
                    continue

                # Add and recurse
                result = count_independent_sets_recursive(node, current_set | {node})
                result += 1  # Count this set as well
            return result

        # Simple enumeration for small sizes
        count = 0
        for mask in range(max_sets):
