                        if adj_mat[i][j]:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                count += 1
        return count

    # Compute for each component
    total_A = 1  # No sum-0 edges
    total_B = 1  # No sum-1 edges  
    total_C = 1  # No sum-2 edges

    for comp in components:
        size = len(comp)
        comp_adj = [[] for _ in range(size)]
        for i, u in enumerate(comp):
            for v in adj[u]:
                if v in comp:
                    j = comp.index(v)
                    comp_adj[i].append(j)

        if size == 0:
            continue

        # |A_i|: No edge is 0-0 → 0s must form independent set
        # This is vertex cover of complement = 2^size - sum(2^remaining) for IS
        # Actually for no 0-0: it's 2^size if we assign 0/1 freely but avoid 0-0
        # Each edge must have at least one 1
        # = sum_{S is IS} 2^{size-|S|} where S are vertices that can be 0

        # Simpler: enumerate all 2^size assignments
        # Count those with no 0-0 edges
        A_i = 0
        for mask in range(1 << size):
            ok = True
            for i in range(size):
                if not ((mask >> i) & 1):
                    continue
                for j in comp_adj[i]:
                    if ((mask >> j) & 1) == 0 and ((mask >> i) & 1) == 0:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                A_i += 1

        # |B_i|: No edge is 0-1 → must be 00 or 11 on each edge
        # This means each connected subgraph is monochromatic
        # Count valid assignments where no edge connects different values
        B_i = 1
        for mask in range(1 << size):
            ok = True
            for i in range(size):
                if not ((mask >> i) & 1):
                    continue
                for j in comp_adj[i]:
                    if ((mask >> j) & 1) != ((mask >> i) & 1):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                B_i += 1

        # |C_i|: No edge is 1-1 → 1s must form independent set
        C_i = 0
        for mask in range(1 << size):
            ok = True
            for i in range(size):
                if (mask >> i) & 1:
                    for j in comp_adj[i]:
                        if (mask >> j) & 1:
                            ok = False
                            break
                    if not ok:
                        break
            if ok:
                C_i += 1

        total_A *= A_i
        total_B *= B_i
        total_C *= C_i

    # Compute intersections
    total_AB = 1  # No sum-0 AND no sum-1
    total_AC = 1  # No sum-0 AND no sum-2  
    total_BC = 1  # No sum-1 AND no sum-2

    for comp in components:
        size = len(comp)
        comp_adj = [[] for _ in range(size)]
        for i, u in enumerate(comp):
            for v in adj[u]:
                if v in comp:
                    j = comp.index(v)
                    comp_adj[i].append(j)

        if size == 0:
            continue

        # A ∩ B: No 0-0 AND No 0-1 → all edges must be 1-1
        AB_i = 0
        for mask in range(1 << size):
            has_edge = False
            ok = True
            for i in range(size):
                for j in comp_adj[i]:
                    if i < j:
                        has_edge = True
                        u_val = (mask >> i) & 1
                        v_val = (mask >> j) & 1
                        if u_val == 0:  # 0-0 forbidden
                            ok = False
                            break
                        if u_val + v_val == 1:  # 0-1 forbidden
                            ok = False
                            break
            if ok:
                # For A ∩ B, edges must be 1-1 or there's no edge
                # No edge has sum 0 or sum 1, so all edges sum to 2 (both vertices 1)
                # This is also checking independent of sum-0, sum-1 constraints
                AB_i += 1

        # A ∩ C: No 0-0 AND No 1-1 → all edges must be 0-1
        AC_i = 0
        for mask in range(1 << size):
            ok = True
            for i in range(size):
                for j in comp_adj[i]:
                    if i < j:
                        u_val = (mask >> i) & 1
                        v_val = (mask >> j) & 1
                        if u_val == v_val:  # 0-0 or 1-1 forbidden
                            ok = False
                            break
            if ok:
                AC_i += 1

        # B ∩ C: No 0-1 AND No 1-1 → all edges must be 0-0
        BC_i = 0
        for mask in range(1 << size):
            ok = True
            for i in range(size):
                for j in comp_adj[i]:
                    if i < j:
                        u_val = (mask >> i) & 1
                        v_val = (mask >> j) & 1
                        if u_val + v_val != 0:  # Not allowed to be 0-1 or 1-1
                            ok = False
                            break
            if ok:
                BC_i += 1

        total_AB *= AB_i
        total_AC *= AC_i
        total_BC *= BC_i

    # A ∩ B ∩ C: All edges must be 0-1 (for A∩C), 1-1 (for A∩B), and 0-0 (for B∩C) simultaneously - impossible
    ABC = 1
    for comp in components:
        size = len(comp)
        if size > 1 and any(adj):  # Has edges
            # Impossible - cannot have edge be both 0-0, 0-1, and 1-1 simultaneously
            ABC = 0
            break
        else:
            ABC *= 1

    # By inclusion-exclusion:
    # Valid = Total - |A ∪ B ∪ C|
    # |A ∪ B ∪ C| = |A| + |B| + |C| - |AB| - |AC| - |BC| + |ABC|

    total_assignments = 1
    for comp in components:
        total_assignments *= (2 ** len(comp))

    invalid = (total_A + total_B + total_C) - (total_AB + total_AC + total_BC) + ABC
    valid = total_assignments - invalid

    return f"{valid}\n"

